] as const;

export const TEXT_TONES = ['primary', 'secondary'] as const;
export const TEXT_ALIGNS = ['start', 'center'] as const;
export const TEXT_WRAPS = ['auto', 'balance', 'pretty'] as const;
export const TEXT_MEASURES = ['none', 'half', 'wide', 'prose', 'narrow'] as const;
export const TEXT_ELEMENTS = ['p', 'span', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'div', 'figcaption', 'blockquote', 'li', 'label'] as const;

export type TextVariant = (typeof TEXT_VARIANTS)[number];
export type TextTone = (typeof TEXT_TONES)[number];
export type TextAlign = (typeof TEXT_ALIGNS)[number];
export type TextWrap = (typeof TEXT_WRAPS)[number];
export type TextMeasure = (typeof TEXT_MEASURES)[number];
export type TextElement = (typeof TEXT_ELEMENTS)[number];

export type TextProps = {
  /** Which of the thirteen text styles to use. Independent from the HTML element. */
  variant?: TextVariant;
  /** Ink: primary (black) or secondary (gray). Text has no other colors, as in the talks. */
  tone?: TextTone;
  /** The HTML element to render. Choose it by document meaning, not by size. */
  as?: TextElement;
  /** Horizontal alignment. */
  align?: TextAlign;
  /** How lines are distributed: balance for titles and sentences, pretty for paragraphs. */
  wrap?: TextWrap;
  /** Maximum width with a name: half (half grid), wide (three quarters), prose (62ch), narrow (38ch). */
  measure?: TextMeasure;
  /** Monospaced, a bit smaller: a command, a file name. */
  mono?: boolean;
  className?: string;
  /** The text. Inside, <strong> goes bold and <code> monospaced, in the same ink. */
  children: ReactNode;
} & Omit<ComponentPropsWithoutRef<'p'>, 'children' | 'className'>;

export const TEXT_DEFAULTS = {
  variant: 'body-m',
  tone: 'primary',
  as: 'p',
  wrap: 'auto',
  measure: 'none',
} as const satisfies Required<Pick<TextProps, 'variant' | 'tone' | 'as' | 'wrap' | 'measure'>>;
import type { ComponentPropsWithoutRef, ReactNode } from 'react';

export const BUTTON_VARIANTS = ['primary', 'outline', 'ghost'] as const;
export const BUTTON_SIZES = ['md', 'sm'] as const;

export type ButtonVariant = (typeof BUTTON_VARIANTS)[number];
export type ButtonSize = (typeof BUTTON_SIZES)[number];

type CommonProps = {
  /** Level of emphasis. Only one `primary` per zone. */
  variant?: ButtonVariant;
  /** Control height: md (45) or sm (36). */
  size?: ButtonSize;
  /** Icon before the label. Inherits the text color. Use a Lucide icon. */
  icon?: ReactNode;
  /** Square button that shows only the icon; the label stays for screen readers. Needs `icon`. */
  iconOnly?: boolean;
  /** The label. Always required: it is the accessible name. */
  children: ReactNode;
  className?: string;
};

type AsButton = CommonProps & {
  href?: undefined;
  /** The action is not possible right now. Never combined with `href`. */
  disabled?: boolean;
  /** The native button type. `submit` only inside a Form; elsewhere leave the default `button`. */
  type?: 'button' | 'submit' | 'reset';
} & Omit<ComponentPropsWithoutRef<'button'>, 'children' | 'className' | 'type' | 'disabled'>;

type AsLink = CommonProps & {
  /** With `href` the button navigates: it renders a real link with the same look. */
  href: string;
  disabled?: never;
  type?: never;
} & Omit<ComponentPropsWithoutRef<'a'>, 'children' | 'className' | 'href'>;

export type ButtonProps = AsButton | AsLink;

export const BUTTON_DEFAULTS = {
  variant: 'primary',
  size: 'md',
  iconOnly: false,
} as const satisfies Required<Pick<CommonProps, 'variant' | 'size' | 'iconOnly'>>;
